// Helper functions for carousel styling
func getCarouselData(items []CarouselItem, autoPlay bool, interval int, loop bool) string {
	// Find the active slide or default to the first one
	activeSlide := 0
	for i, item := range items {
		if item.Active {
			activeSlide = i
			break
		}
	}

	intervalStr := "3000"
	if interval > 0 {
		intervalStr = strconv.Itoa(interval)
	}

	return `{
		currentSlide: ` + strconv.Itoa(activeSlide) + `,
		totalSlides: ` + strconv.Itoa(len(items)) + `,
		autoPlay: ` + getCarouselBoolString(autoPlay) + `,
		interval: ` + intervalStr + `,
		loop: ` + getCarouselBoolString(loop) + `,
		timer: null,
		
		init() {
			if (this.autoPlay) {
				this.startAutoPlay();
			}
		},
		
		startAutoPlay() {
			this.timer = setInterval(() => {
				this.nextSlide();
			}, this.interval);
		},
		
		stopAutoPlay() {
			if (this.timer) {
				clearInterval(this.timer);
				this.timer = null;
			}
		},
		
		goToSlide(index) {
			this.currentSlide = index;
			if (this.autoPlay) {
				this.stopAutoPlay();
				this.startAutoPlay();
			}
		},
		
		nextSlide() {
			if (this.currentSlide < this.totalSlides - 1) {
				this.currentSlide++;
			} else if (this.loop) {
				this.currentSlide = 0;
			}
		},
		
		prevSlide() {
			if (this.currentSlide > 0) {
				this.currentSlide--;
			} else if (this.loop) {
				this.currentSlide = this.totalSlides - 1;
			}
		}
	}`
}

func getCarouselClasses(height string) string {
	base := "relative w-full"

	var heightClass string
	switch height {
	case "sm":
		heightClass = "h-56"
	case "lg":
		heightClass = "h-96"
	case "xl":
		heightClass = "h-[32rem]"
	case "2xl":
		heightClass = "h-[40rem]"
	case "auto":
		heightClass = ""
	default: // base
		heightClass = "h-80"
	}

	if heightClass == "" {
		return base
	}
	return strings.Join([]string{base, heightClass}, " ")
}

